import random


class DynamicMaskingTrainer:
    def __init__(self, mask_rate: float = 0.15):
        self.mask_rate = mask_rate

    def _count(self, n: int) -> int:
        if n == 0:
            return 0
        return min(n, max(1, int(n * self.mask_rate)))

    def _apply(self, words, positions) -> str:
        chosen = set(positions)
        return " ".join("<mask>" if i in chosen else w for i, w in enumerate(words))

    def static_mask(self, sentence: str, seed: int = 42) -> str:
        # BERT-style: pattern is a pure function of (sentence length, seed)
        words = sentence.split()
        n = len(words)
        k = self._count(n)
        if k == 0:
            return sentence
        start = seed % max(1, n - 1)
        step = max(1, n // k)
        positions = []
        i = start
        while len(positions) < k:
            if i % n not in positions:
                positions.append(i % n)
            i += step
            if i - start > 4 * n:  # safety fallback for odd step/size combos
                break
        j = 0
        while len(positions) < k:
            if j not in positions:
                positions.append(j)
            j += 1
        return self._apply(words, positions)

    def dynamic_mask(self, sentence: str) -> str:
        # RoBERTa-style: fresh random pattern on every call
        words = sentence.split()
        n = len(words)
        k = self._count(n)
        if k == 0:
            return sentence
        return self._apply(words, random.sample(range(n), k))

    def training_diversity(self, sentence: str, epochs: int) -> dict:
        static_seen = set()
        dynamic_seen = set()
        for _ in range(epochs):
            static_seen.add(self.static_mask(sentence, seed=42))
            dynamic_seen.add(self.dynamic_mask(sentence))
        return {"static": len(static_seen), "dynamic": len(dynamic_seen)}


# Test it:
trainer = DynamicMaskingTrainer(mask_rate=0.3)

# Static always gives same result
print(trainer.static_mask("the cat sat on the mat", seed=42))
print(trainer.static_mask("the cat sat on the mat", seed=42))

# Check diversity over many epochs
result = trainer.training_diversity("the cat sat on the mat", epochs=50)
print(result["static"])
print(result["dynamic"] > result["static"])

class MaskPredictionComparator:
    def __init__(self, models: dict):
        self.models = models

    def predict(self, model_name: str, masked_sentence: str) -> dict:
        sentence = masked_sentence.lower()
        best_key = "[UNK]"
        best_score = 0.0
        best_count = 0
        for key, info in self.models.get(model_name, {}).items():
            count = sum(1 for w in info["words"] if w.lower() in sentence)
            if count > best_count:
                best_count = count
                best_key = key
                best_score = info["score"]
        return {"token": best_key, "score": best_score, "model": model_name}

    def compare(self, masked_sentence: str) -> str:
        results = [self.predict(name, masked_sentence) for name in self.models]
        if not results:
            return "tie"
        top = max(r["score"] for r in results)
        winners = [r["model"] for r in results if r["score"] == top]
        return winners[0] if len(winners) == 1 else "tie"


models = {
    "bert": {
        "paper": {"words": ["publish", "journal", "research"], "score": 0.82},
        "code": {"words": ["program", "software", "python"], "score": 0.75}
    },
    "roberta": {
        "paper": {"words": ["publish", "journal", "research"], "score": 0.95},
        "code": {"words": ["program", "software", "python"], "score": 0.91}
    }
}

comp = MaskPredictionComparator(models)

result = comp.predict("roberta", "the researcher will publish a <mask> in the journal")
print(result["token"])
print(result["score"])

winner = comp.compare("the researcher will publish a <mask> in the journal")
print(winner)
